<?php $defaultConnectionColumns=['email','first_name','last_name','tags','email_status','source','created_at'];$columns=['email'=>'Email Address','first_name'=>'First Name','last_name'=>'Last Name','tags'=>'Tags','email_status'=>'Email Marketing','source'=>'Source','created_at'=>'Date Added','updated_at'=>'Last Changed'];foreach($groups as$group)$columns['group:'.$group['id']]='Groups: '.$group['name'];foreach($fields as$field)$columns['custom:'.$field['id']]=$field['label']; ?>
<form class="audience-filters audience-filter-popovers" method="get"><?php audienceInputs($baseForm+['archived'=>$filters['archived'],'rules'=>json_encode($rules,JSON_THROW_ON_ERROR)]); ?>
    <label class="audience-people-search"><span class="sr-only">Search connections</span><?php audienceNavIcon('search'); ?><input id="contact-search" type="search" name="q" placeholder="Search connections" value="<?= $h($filters['q']) ?>"></label>
    <button type="button" class="audience-filter-trigger" popovertarget="filter-segments" aria-haspopup="dialog" title="Filter by Segments"><?= $segment?$h($segment['name']):'Segments' ?><?php audienceNavIcon('chevron'); ?></button>
    <div id="filter-segments" class="audience-filter-panel" popover="auto" role="dialog" aria-label="Filter by Segments" data-filter-panel>
        <label class="filter-search"><?php audienceNavIcon('search'); ?><input type="search" placeholder="Search" aria-label="Search segments" data-filter-search></label>
        <div class="filter-choice-scroll"><?php foreach($segments as$s): ?><a data-filter-choice href="<?= $h($url(['segment'=>$s['id']])) ?>"><?= $h($s['name']) ?></a><?php endforeach; ?><?php if(!$segments): ?><p class="filter-empty">No saved segments yet.</p><?php endif; ?><p class="filter-empty" data-filter-empty hidden>No matching segments</p></div>
        <a class="filter-manage-link" href="<?= $h($url(['view'=>'segments'])) ?>">Manage segments</a>
    </div>
    <?php $statusHelp=['subscribed'=>'Opted in to email marketing','unsubscribed'=>'Opted out after subscribing','non-subscribed'=>'Never opted in to email marketing','cleaned'=>'Email address is invalid or bounced']; ?>
    <?php foreach(['status'=>'Subscription status','tags'=>'Tags','source'=>'Signup source']as$key=>$label): $options=$key==='status'?array_combine(array_keys($statusHelp),array_map('ucfirst',array_keys($statusHelp))):($key==='tags'?array_column($tags,'name','id'):array_column($sources,'source','source')); ?>
    <button type="button" class="audience-filter-trigger<?= count($filters[$key])?' active':'' ?>" popovertarget="filter-<?= $key ?>" aria-haspopup="dialog" title="Filter by <?= $label ?>"><?= $label ?><?= count($filters[$key])?' ('.count($filters[$key]).')':'' ?><?php audienceNavIcon('chevron'); ?></button>
    <div id="filter-<?= $key ?>" class="audience-filter-panel" popover="auto" role="dialog" aria-label="Filter by <?= $label ?>" data-filter-panel>
        <?php if($key==='status'): ?><div class="filter-section-label">Email</div><?php else: ?><label class="filter-search"><?php audienceNavIcon('search'); ?><input type="search" placeholder="Search" aria-label="Search <?= strtolower($label) ?>" data-filter-search></label><?php endif; ?>
        <div class="filter-choice-scroll"><?php foreach($options as$value=>$text): ?><label class="filter-option" data-filter-choice><input type="checkbox" name="<?= $key ?>[]" value="<?= $h($value) ?>" data-instant-filter="<?= $key ?>"<?= in_array((string)$value,array_map('strval',$filters[$key]),true)?' checked':'' ?><?= $key==='status'?' aria-describedby="status-help-'.$h($value).'"':'' ?>><span><?= $h($text) ?><?php if($key==='status'): ?><small id="status-help-<?= $h($value) ?>"><?= $h($statusHelp[$value]) ?></small><?php endif; ?></span></label><?php endforeach; ?><?php if(!$options): ?><p class="filter-empty">No <?= strtolower($label) ?> yet.</p><?php endif; ?><p class="filter-empty" data-filter-empty hidden>No matches found</p></div>
        <?php if($key==='tags'): ?><a class="filter-manage-link" href="<?= $h($url(['view'=>'tags'])) ?>">Manage tags</a><?php endif; ?>
    </div>
    <?php endforeach; ?>
    <?php if($canManage): ?><button type="button" class="audience-advanced-filters" data-segment-current><?php audienceNavIcon('filters'); ?>Advanced filters</button><?php endif; ?>
    <button type="submit" class="filter-search-submit sr-only" aria-label="Search connections">Search</button><?php if($filters['q']!==''||$filters['status']||$filters['tags']||$filters['source']||($rules['rules']??[])): ?><a class="text-link" href="<?= $h($url()) ?>">Clear filters</a><?php endif; ?>
</form>
<?php if($rules['rules']??[]): ?><div class="audience-applied-rules"><span>Advanced filters applied<?= $segment?' · '.$h($segment['name']):'' ?></span><?php if($canManage): ?><button class="text-button" data-segment-current>Edit filters</button><?php endif; ?></div><?php endif; ?>
<div class="audience-counts"><p><a href="<?= $h($url()) ?>"><strong><?= number_format((int)$counts['total']) ?></strong></a> total connections. <a href="<?= $h($url(['status'=>['subscribed']])) ?>"><strong><?= number_format((int)$counts['subscribed']) ?></strong></a> email subscribers.</p></div>
<section class="audience-table-card" aria-label="Connections">
    <div class="audience-table-tools"><span><?= number_format($total) ?> matching <?= $filters['archived']==='1'?'archived ':'' ?>connections</span><div><button type="button" class="text-button audience-columns-trigger" popovertarget="columns" aria-haspopup="dialog">Columns <?php audienceNavIcon('chevron'); ?></button>
        <?php if($canExport): ?><form method="post" id="people-export"><?= $csrf ?><?php audienceInputs($baseForm+$query+['action'=>'queue_export','selection_scope'=>'all']); ?><span data-export-selection></span><button class="text-button" type="submit" data-export-label>↓ Export connections</button></form><?php endif; ?>
    </div></div>
    <?php if($canManage): ?><div class="audience-bulk-toolbar" hidden data-bulk-toolbar><span data-selection-count>0 connections selected</span><button class="text-button" data-select-matches type="button">Select all <?= number_format($total) ?> matching connections</button><button type="button" data-open-dialog="bulk-people">Actions ⌄</button><button class="text-button" data-clear-selection type="button">Clear selection</button></div><?php endif; ?>
    <div class="audience-table-scroll"><table class="audience-table" data-people-table><thead><tr>
        <?php if($canManage): ?><th class="selection-cell"><input type="checkbox" data-select-page aria-label="Select this page"></th><?php endif; ?>
        <?php foreach($columns as$key=>$label): ?><th scope="col" data-column="<?= $h($key) ?>"<?= !in_array($key,$defaultConnectionColumns,true)?' hidden':'' ?><?= in_array($key,$sortColumns,true)?' aria-sort="'.($sort===$key?($direction==='asc'?'ascending':'descending'):'none').'"':'' ?>><?php if(in_array($key,$sortColumns,true)): ?><a href="<?= $h($url(array_replace($query,['sort'=>$key,'direction'=>$sort===$key&&$direction==='asc'?'desc':'asc']))) ?>"><?= $h($label) ?><?= $sort===$key?($direction==='asc'?' ↑':' ↓'):'' ?></a><?php else: ?><?= $h($label) ?><?php endif; ?></th><?php endforeach; ?>
    </tr></thead><tbody>
    <?php foreach($rows as$row): $custom=audienceJson($row['custom_json']); ?><tr>
        <?php if($canManage): ?><td class="selection-cell"><input type="checkbox" data-person-select value="<?= (int)$row['id'] ?>" aria-label="Select <?= $h($row['email']) ?>"></td><?php endif; ?>
        <?php foreach($columns as$key=>$label): ?><td data-column="<?= $h($key) ?>"<?= !in_array($key,$defaultConnectionColumns,true)?' hidden':'' ?>>
            <?php if($key==='email'): ?><a href="<?= $h($url(['view'=>'contact','id'=>$row['id']])) ?>"><?= $h($row['email']) ?></a>
            <?php elseif($key==='tags'): $connectionTags=$rowTags[$row['id']]; foreach(array_slice($connectionTags,0,6)as$tag): ?><a class="audience-tag" href="<?= $h($url(['tags'=>[$tag['id']]])) ?>"><?= $h($tag['name']) ?></a><?php endforeach; ?><?php if(count($connectionTags)>6): ?><a class="audience-tag" href="<?= $h($url(['view'=>'contact','id'=>$row['id']])) ?>" aria-label="View all <?= count($connectionTags) ?> tags" title="View all <?= count($connectionTags) ?> tags">[...]</a><?php endif; ?>
            <?php elseif(str_starts_with($key,'group:')): foreach($rowGroups[$row['id']]as$group): if((string)$group['category_id']!==substr($key,6))continue; ?><span class="audience-tag" title="<?= $h($group['category']) ?>"><?= $h($group['name']) ?></span><?php endforeach; ?>
            <?php elseif($key==='email_status'): ?><span class="audience-status <?= $h($row[$key]) ?>"><?= $h(ucfirst($row[$key])) ?></span>
            <?php elseif(str_starts_with($key,'custom:')): $v=$custom[substr($key,7)]??''; ?><?= $h(is_array($v)?implode(', ',$v):$v) ?>
            <?php else: ?><?= $h(in_array($key,['created_at','updated_at'],true)?substr($row[$key],0,16):$row[$key]) ?><?php endif; ?>
        </td><?php endforeach; ?>
    </tr><?php endforeach; ?>
    <?php if(!$rows): ?><tr><td colspan="<?= count($columns)+($canManage?1:0) ?>" class="audience-empty"><h2><?= (int)$counts['total']===0?'Build your audience':'No connections found' ?></h2><p><?= (int)$counts['total']===0?'Import your connections or add a connection to get started.':'Try another search or change your filters.' ?></p><?php if($canManage): ?><a class="button primary" href="<?= $h($url(['view'=>'import'])) ?>">Import connections</a><?php endif; ?></td></tr><?php endif; ?>
    </tbody></table></div>
    <div class="audience-pagination"><form method="get"><?php audienceInputs($baseForm+array_diff_key($query,['per_page'=>1])); ?><label for="page-size">Items per page</label> <select id="page-size" name="per_page" data-auto-submit><?php foreach([10,25,50,100]as$n): ?><option<?= $pageSize===$n?' selected':'' ?>><?= $n ?></option><?php endforeach; ?></select></form><span><?= $total?number_format(($page-1)*$pageSize+1).'–'.number_format(min($page*$pageSize,$total)):'0' ?> of <?= number_format($total) ?></span><div><?php if($page>1): ?><a class="button" aria-label="Previous page" href="<?= $h($url($query+['page'=>$page-1])) ?>">←</a><?php endif; ?><span><?= $page ?> / <?= max(1,(int)ceil($total/$pageSize)) ?></span><?php if($page*$pageSize<$total): ?><a class="button" aria-label="Next page" href="<?= $h($url($query+['page'=>$page+1])) ?>">→</a><?php endif; ?></div></div>
</section>
<div id="columns" class="audience-columns-panel" popover="auto" role="dialog" aria-labelledby="columns-title">
    <div class="dialog-heading"><h2 id="columns-title">Columns</h2><button type="button" popovertarget="columns" popovertargetaction="hide" aria-label="Close columns">×</button></div>
    <p>Customize how columns appear or go to <a href="<?= $h($url(['view'=>'fields'])) ?>">audience fields</a> to add new audience fields.</p>
    <p class="sr-only" id="columns-reorder-help">Drag a handle to reorder a column, or focus its handle and press the Up or Down arrow key. Select Apply to save changes.</p>
    <div data-column-list><?php foreach($columns as$key=>$label): ?><div class="column-choice" data-column-choice="<?= $h($key) ?>"><label class="audience-check"><input type="checkbox" data-column-toggle="<?= $h($key) ?>"<?= in_array($key,$defaultConnectionColumns,true)?' checked':'' ?><?= $key==='email'?' disabled':'' ?>><span><?= $h($label) ?></span></label><?php if($key!=='email'): ?><button type="button" class="column-drag-handle" data-column-drag aria-label="Reorder <?= $h($label) ?>" aria-describedby="columns-reorder-help"><?php audienceNavIcon('grip'); ?></button><?php endif; ?></div><?php endforeach; ?></div>
    <p class="sr-only" role="status" data-column-announcement></p>
    <div class="columns-footer"><button type="button" class="primary" data-apply-columns>Apply</button></div>
</div>
